mapper.select:
SELECT  FROM `camera_capture_plan` cp
JOIN `camera_device` c ON c.id = cp.device_id
JOIN `plot` p ON p.id = cp.plot_id WHERE cp.id = #{id}

SELECT  FROM `camera_capture_plan` cp
JOIN `camera_device` c ON c.id = cp.device_id
JOIN `plot` p ON p.id = cp.plot_id

    AND cp.user_id = #{userId}
    AND cp.plot_id = #{plotId}
    AND cp.enabled = #{enabled}

        AND (cp.plan_name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY cp.enabled DESC, cp.id DESC
